#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
AI解决率看板 · VPS 自动化部署包 v6
=====================================
在 VPS 上跑这一个文件，自动把所有脚本还原到 /root/bi_dashboard/v5scripts/
用法: python3 deploy_v6.py
"""
import base64, os

TARGET = "/root/bi_dashboard/v5scripts"
os.makedirs(TARGET, exist_ok=True)
os.makedirs("/root/bi_dashboard/v5data/full_data", exist_ok=True)
os.makedirs("/root/bi_dashboard/v5output", exist_ok=True)

FILES = {
    'gen_line_v5.py': """""",
    'render_line_v5.py': """""",
    'gen_dept_data.py': """""",
    'gen_dept_v5.py': """""",
    'gen_tg_v5.py': """""",
    'gen_zip_v5.py': """""",
    'run_daily.sh': """""",
}

for fn, b64 in FILES.items():
    path = os.path.join(TARGET, fn)
    with open(path, 'wb') as f:
        f.write(base64.b64decode(b64))
    if fn.endswith('.sh'):
        os.chmod(path, 0o755)
    print(f'  还原 {path}')

print()
print('='*50)
print('✅ 部署完成！6 脚本 + run_daily.sh 已还原')
print('   目录: ' + TARGET)
print('='*50)
print()
print('下一步（手动测试一次，先别配 cron）：')
print('  1. 把当天两个 xlsx 放到 /root/bi_dashboard/input/')
print('     命名: 客服對話_1-1_2026-06-09_完整對話.xlsx')
print('  2. 把历史档（5/29-6/8 的 full_data JSON）放到')
print('     /root/bi_dashboard/v5data/full_data/')
print('  3. 跑: cd /root/bi_dashboard/v5scripts && \\')
print('         BI_BASE=/root/bi_dashboard/v5data \\')
print('         BI_OUT=/root/bi_dashboard/v5output \\')
print('         PY=/root/bi_dashboard/venv/bin/python \\')
print('         SCRIPTS=/root/bi_dashboard/v5scripts \\')
print('         IN_DIR=/root/bi_dashboard/input \\')
print('         bash run_daily.sh 2026-06-09')
print('  4. 看 /root/bi_dashboard/v5output/ 是否出 15 档 + ZIP')
